<script module lang="ts">
/**
 * A file attached to a prompt, shown as a chip (`design/components/attachment-chip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/attachment-chip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  formatBytes,
  joinSlot,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/attachment-chip.module.css'
import Button from '../controls/Button.svelte'
import Link from '../controls/Link.svelte'
import Spinner from '../structure/Spinner.svelte'

export type AttachmentStatus = 'uploading' | 'done' | 'error'

export interface AttachmentChipProps {
  /**
   * The file's URL, which makes the name a link that opens in a new tab (Link's `external`).
   */
  href?: string
  /**
   * The leading mark, `document` by default, or `table` or `browser` when the app knows the
   * kind.
   */
  icon?: IconRole
  /**
   * The app's text for a failure, which the chip never writes itself.
   */
  message?: string
  /**
   * The file's name, ellipsed when the row is narrow.
   */
  name: string
  /**
   * Shows the remove button when supplied, and is omitted in a sent message, where removal is
   * over.
   */
  onRemove?: () => void
  /**
   * The remove button's accessible name (default `Remove {name}`), which apps pass to localize.
   */
  removeLabel?: string
  /**
   * The size in bytes, formatted by the engine's `formatBytes`, as FileUpload's rows are, so
   * sizes match in both places.
   */
  size?: number
  /**
   * The upload status, where `done` is the rest state.
   */
  status?: 'error' | 'uploading' | 'done'
  /**
   * The status announced while the file uploads (default `{name}: uploading`), which apps pass
   * to localize.
   */
  uploadingLabel?: string
}
</script>

<script lang="ts">
let {
  href,
  icon = 'document',
  message,
  name,
  onRemove,
  removeLabel,
  size,
  status = 'done',
  uploadingLabel,
}: AttachmentChipProps = $props()
const joined = joinSlot(undefined, () => ({ name: name, size: size }))
const listening = {
  get remove() {
    return onRemove !== undefined
  },
}
let chip = $state<HTMLElement | null>(null)
let file = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'AttachmentChip',
    element: () => file,
    state: () => ({ name: name, status: status }),
    actions: {
      remove: () =>
        (() => {
          if (!listening.remove)
            throw new Error('The chip records a sent file and has no remove control.')
          onRemove?.()
        })(),
    },
    withholds: () => chip,
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span bind:this={chip} class={styles.chip} data-status={status} data-member="attachment-chip"
    ><span class={styles.mark}
      >{#if status === 'uploading'
        }<Spinner size="sm" label={uploadingLabel ?? `${name}: uploading`}
      />{:else if status === 'error'
        }<Icon name="error" size="sm"
      />{:else
        }<Icon name={icon} size="sm"
      />{/if
    }</span
    ><span class={styles.body}
      ><span bind:this={file} class={styles.name}
        >{#if href === undefined}{name}{:else}<Link {href} external={true}>{name}</Link>{/if
      }</span
      >{#if size !== undefined && status !== 'error'
        }<span class={styles.meta}>{formatBytes(size)}</span
      >{/if
      }{#if status === 'error' && message !== undefined
        }<span class={styles.message}>{message}</span
      >{/if
    }</span
    >{#if listening.remove
      }<Button
        variant="ghost"
        tone="neutral"
        size="sm"
        iconOnly={true}
        icon="close"
        label={removeLabel ?? `Remove ${name}`}
        onClick={() => { onRemove?.() }}
    />{/if
  }</span
>{/if
}{@render joined.end?.()}
